import zipfile,xml.etree.ElementTree as ET
p='/home/user/workspace/out_b/Product_Launch_Final.pptx'
z=zipfile.ZipFile(p)
ns={'a':'http://schemas.openxmlformats.org/drawingml/2006/main','p':'http://schemas.openxmlformats.org/presentationml/2006/main'}
for i in range(1,5):
 r=ET.fromstring(z.read(f'ppt/slides/slide{i}.xml'))
 print('\nSLIDE',i)
 for sp in r.findall('.//p:sp',ns):
  name=sp.find('./p:nvSpPr/p:cNvPr',ns).get('name')
  off=sp.find('./p:spPr/a:xfrm/a:off',ns); ext=sp.find('./p:spPr/a:xfrm/a:ext',ns)
  x,y,cx,cy=('',)*4
  if off is not None:x,y=off.get('x'),off.get('y');cx,cy=ext.get('cx'),ext.get('cy')
  tx='|'.join(''.join(p.itertext()) for p in sp.findall('.//a:p',ns))
  print(name,tuple(round(int(v)/914400,2) for v in (x,y,cx,cy)) if x else '',repr(tx))
 for gf in r.findall('.//p:graphicFrame',ns):
  print('TABLE')
  for tr in gf.findall('.//a:tr',ns): print([''.join(t.itertext()) for t in tr.findall('./a:tc/a:txBody/a:p',ns)])
